from merge import merge_dicts


def test_merge():
    a = {'x': 1}
    b = {'y': 2}
    merged = merge_dicts(a, b)
    assert merged == {'x': 1, 'y': 2}
    assert a == {'x': 1}
    assert b == {'y': 2}
